      size: 17,
      weight: 800,
      color: "#F2D8C5"
    });
    drawCenteredText(context, parts.date, centerX, TABLE_TOP + 67, {
      size: 23,
      weight: 820,
      color: "#FFFFFF"
    });
  });
}

function drawPersonRows(context, state, dateKeys, people, tableWidth, dateColumnWidth) {
  const rowsTop = TABLE_TOP + TABLE_HEADER_HEIGHT;
  context.textBaseline = "middle";

  people.forEach((person, rowIndex) => {
    const y = rowsTop + rowIndex * ROW_HEIGHT;
    context.fillStyle = rowIndex % 2 ? "#FFFBF7" : "#FFFFFF";
    context.fillRect(SIDE_MARGIN, y, tableWidth, ROW_HEIGHT);

    context.strokeStyle = "#EEE4DA";
    context.lineWidth = 1;
    context.beginPath();
    context.moveTo(SIDE_MARGIN, y + ROW_HEIGHT);
    context.lineTo(SIDE_MARGIN + tableWidth, y + ROW_HEIGHT);
    context.stroke();

    context.fillStyle = "#302923";
    context.font = `720 22px ${FONT_FAMILY}`;
    context.textAlign = "left";
    const visibleName = truncateText(context, person.name, NAME_COLUMN_WIDTH - 48);
    context.fillText(visibleName, SIDE_MARGIN + 24, y + ROW_HEIGHT / 2 + 1);

    dateKeys.forEach((dateKey, dateIndex) => {
      const centerX = SIDE_MARGIN + NAME_COLUMN_WIDTH + dateColumnWidth * dateIndex + dateColumnWidth / 2;
      const status = getEntry(state, dateKey, person.id)?.status;
      drawStatusCell(context, status, centerX, y + ROW_HEIGHT / 2);
    });
  });

  context.strokeStyle = "#E8DCD1";
  context.lineWidth = 2;
  for (let index = 0; index <= dateKeys.length; index += 1) {
    const x = SIDE_MARGIN + NAME_COLUMN_WIDTH + dateColumnWidth * index;
    context.beginPath();
    context.moveTo(x, TABLE_TOP);
    context.lineTo(x, rowsTop + people.length * ROW_HEIGHT + TOTALS_HEIGHT);
    context.stroke();
  }
}

function drawTotals(context, state, dateKeys, allPeople, peopleCount, tableWidth, dateColumnWidth) {
  const y = TABLE_TOP + TABLE_HEADER_HEIGHT + peopleCount * ROW_HEIGHT;
  context.fillStyle = "#F7EFE7";
  context.fillRect(SIDE_MARGIN, y, tableWidth, TOTALS_HEIGHT);

  context.fillStyle = "#6C5F55";
  context.font = `800 17px ${FONT_FAMILY}`;
  context.textAlign = "left";
  context.textBaseline = "middle";
  context.fillText("ИТОГО", SIDE_MARGIN + 24, y + TOTALS_HEIGHT / 2);

  dateKeys.forEach((dateKey, index) => {
    const counts = statusDistribution(state, dateKey, allPeople);
    const centerX = SIDE_MARGIN + NAME_COLUMN_WIDTH + dateColumnWidth * index + dateColumnWidth / 2;
    drawCenteredText(context, `${counts.present}/${allPeople.length}`, centerX, y + 35, {
      size: 23,
      weight: 850,
      color: STATUS_META.present.darkColor
    });
    drawCenteredText(context, `Б ${counts.sick} · З ${counts.drunk} · Н ${counts.absent}`, centerX, y + 67, {
      size: 12,
      weight: 720,
      color: "#75695F"
    });
  });
}

function drawFooter(context, footerTop, pageNumber, pageCount) {
  const legendY = footerTop + 45;
  let x = SIDE_MARGIN;

  for (const status of STATUS_KEYS) {
    const meta = STATUS_META[status];
    fillRoundedRect(context, x, legendY - 16, 32, 32, 10, meta.color);
    drawCenteredText(context, meta.mark, x + 16, legendY + 1, { size: 16, weight: 900, color: "#FFFFFF" });
    context.fillStyle = "#514840";
    context.font = `650 18px ${FONT_FAMILY}`;
    context.textAlign = "left";
    context.textBaseline = "middle";
    const label = status === "present" ? "Присутствует" : meta.compactLabel;
    context.fillText(label, x + 43, legendY);
    x += status === "present" ? 220 : 190;
  }

  if (pageCount > 1) {
    context.fillStyle = "#A09489";
    context.font = `550 16px ${FONT_FAMILY}`;
    context.textAlign = "right";
    context.fillText(`Страница ${pageNumber} из ${pageCount}`, IMAGE_WIDTH - SIDE_MARGIN, legendY);
  }
}

function canvasToBlob(canvas) {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("Could not create overview image"));
    }, "image/png");
  });
}

export function getOverviewCanvasHeight(rowCount) {
  return TABLE_TOP + TABLE_HEADER_HEIGHT + rowCount * ROW_HEIGHT + TOTALS_HEIGHT + FOOTER_HEIGHT;
}

export function paginatePeople(people, pageSize = OVERVIEW_PAGE_SIZE) {
  if (!people.length) return [];
  const pages = [];
  for (let index = 0; index < people.length; index += pageSize) {
    pages.push(people.slice(index, index + pageSize));
  }
  return pages;
}

export async function generateOverviewFiles(state, dateKeys) {
  const allPeople = getOverviewPeople(state, dateKeys);
  const pages = paginatePeople(allPeople);
  const files = [];

  for (let pageIndex = 0; pageIndex < pages.length; pageIndex += 1) {
    const people = pages[pageIndex];
    const pageCount = pages.length;
    const tableWidth = IMAGE_WIDTH - SIDE_MARGIN * 2;
    const dateColumnWidth = (tableWidth - NAME_COLUMN_WIDTH) / dateKeys.length;
    const canvasHeight = getOverviewCanvasHeight(people.length);
    if (canvasHeight > MAX_OVERVIEW_CANVAS_HEIGHT) {
      throw new RangeError(`Overview page exceeds the safe canvas height: ${canvasHeight}px`);
    }
    const canvas = document.createElement("canvas");
    canvas.width = IMAGE_WIDTH;
    canvas.height = canvasHeight;
    const context = canvas.getContext("2d", { alpha: false });
    if (!context) throw new Error("Canvas is unavailable");

    const background = context.createLinearGradient(0, 0, IMAGE_WIDTH, canvasHeight);
    background.addColorStop(0, "#FFFBF5");
    background.addColorStop(1, "#F8EEE4");
    context.fillStyle = background;
    context.fillRect(0, 0, IMAGE_WIDTH, canvasHeight);

    drawHeader(context, dateKeys, pageIndex + 1, pageCount);
    drawTableHeader(context, dateKeys, tableWidth, dateColumnWidth);
    drawPersonRows(context, state, dateKeys, people, tableWidth, dateColumnWidth);
    drawTotals(context, state, dateKeys, allPeople, people.length, tableWidth, dateColumnWidth);
    drawFooter(
      context,
      TABLE_TOP + TABLE_HEADER_HEIGHT + people.length * ROW_HEIGHT + TOTALS_HEIGHT,
      pageIndex + 1,
      pageCount
    );

    const blob = await canvasToBlob(canvas);
    const suffix = pageCount > 1 ? `-${pageIndex + 1}` : "";
    const fileName = `poseshchaemost-${dateKeys.at(-1)}${suffix}.png`;
    files.push(new File([blob], fileName, { type: "image/png", lastModified: Date.now() }));
  }

  return files;
}

import { normalizeState } from "./model.js";

const DATABASE_NAME = "attendance-pwa";
const DATABASE_VERSION = 1;
const STORE_NAME = "documents";
const STATE_KEY = "app-state";
const MIRROR_KEY = "attendance-pwa.state.v1";
let indexedWriteQueue = Promise.resolve();

function openDatabase() {
  return new Promise((resolve, reject) => {
    if (!("indexedDB" in globalThis)) {
      reject(new Error("IndexedDB is unavailable"));
      return;
    }

    const request = indexedDB.open(DATABASE_NAME, DATABASE_VERSION);
    request.onupgradeneeded = () => {
      const database = request.result;
      if (!database.objectStoreNames.contains(STORE_NAME)) database.createObjectStore(STORE_NAME);
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error("Could not open IndexedDB"));
    request.onblocked = () => reject(new Error("IndexedDB upgrade was blocked"));
  });
}

async function readIndexedState() {
  const database = await openDatabase();
  try {
    return await new Promise((resolve, reject) => {
      const transaction = database.transaction(STORE_NAME, "readonly");
      const request = transaction.objectStore(STORE_NAME).get(STATE_KEY);
      request.onsuccess = () => resolve(request.result ?? null);
      request.onerror = () => reject(request.error ?? new Error("Could not read IndexedDB"));
    });
  } finally {
    database.close();
  }
}

async function writeIndexedState(state) {
  const database = await openDatabase();
  try {
    await new Promise((resolve, reject) => {
      const transaction = database.transaction(STORE_NAME, "readwrite");
      transaction.objectStore(STORE_NAME).put(state, STATE_KEY);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error ?? new Error("Could not write IndexedDB"));
      transaction.onabort = () => reject(transaction.error ?? new Error("IndexedDB write was aborted"));
    });
  } finally {
    database.close();
  }
}

function readMirroredState() {
  try {
    const raw = localStorage.getItem(MIRROR_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function writeMirroredState(state) {
  try {
    localStorage.setItem(MIRROR_KEY, JSON.stringify(state));
    return true;
  } catch {
    return false;
  }
}

export function chooseNewestState(indexedState, mirroredState) {
  if (indexedState && !mirroredState) return indexedState;
  if (mirroredState && !indexedState) return mirroredState;
  if (!indexedState && !mirroredState) return null;
  const indexedRevision = Number(indexedState.revision) || 0;
  const mirroredRevision = Number(mirroredState.revision) || 0;
  if (indexedRevision !== mirroredRevision) {
    return indexedRevision > mirroredRevision ? indexedState : mirroredState;
  }

  const indexedUpdatedAt = Number(indexedState.updatedAt) || 0;
  const mirroredUpdatedAt = Number(mirroredState.updatedAt) || 0;
  if (indexedUpdatedAt !== mirroredUpdatedAt) {
    return indexedUpdatedAt > mirroredUpdatedAt ? indexedState : mirroredState;
  }

  // The mirror is written synchronously before the queued IndexedDB write.
  return mirroredState;
}

export async function loadState() {
  const mirrored = readMirroredState();
  let indexed = null;

  try {
    indexed = await readIndexedState();
  } catch {
    // The mirrored state keeps the app usable if IndexedDB is temporarily unavailable.
  }

  const newest = chooseNewestState(indexed, mirrored);
  return normalizeState(newest);
}

export function saveState(state) {
  state.revision = (Number.isSafeInteger(state.revision) ? state.revision : 0) + 1;
  state.updatedAt = Date.now();
  const normalized = normalizeState(state);
  const mirrorSaved = writeMirroredState(normalized);
  const indexedWrite = indexedWriteQueue
    .catch(() => undefined)
    .then(() => writeIndexedState(normalized));
  indexedWriteQueue = indexedWrite;

  return indexedWrite
    .then(() => normalized)
    .catch((error) => {
      if (!mirrorSaved) throw error;
      return normalized;
    });
}

export async function requestPersistentStorage() {
  if (!navigator.storage?.persist) return false;
  try {
    if (await navigator.storage.persisted?.()) return true;
    return await navigator.storage.persist();
  } catch {
    return false;
  }
}

import {
  HISTORY_WINDOW_DAYS,
  SCHEMA_VERSION,
  STATUS_KEYS,
  isValidStatus
} from "./constants.js";
import { isDateKey, toDateKey } from "./dates.js";

const MAX_NAME_LENGTH = 80;

function makeId() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  return `person-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function normalizeName(value) {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, MAX_NAME_LENGTH);
}

function clone(value) {
  return typeof structuredClone === "function"
    ? structuredClone(value)
    : JSON.parse(JSON.stringify(value));
}

export function createEmptyState(now = Date.now()) {
  return {
    schemaVersion: SCHEMA_VERSION,
    people: [],
    attendance: {},
    initializedDays: {},
    settings: {
      historyWindowDays: HISTORY_WINDOW_DAYS
    },
    revision: 0,
    createdAt: now,
    updatedAt: now
  };
}

export function normalizeState(input, now = Date.now()) {
  if (!input || typeof input !== "object") return createEmptyState(now);

  const output = createEmptyState(Number(input.createdAt) || now);
  const rawPeople = Array.isArray(input.people) ? input.people : [];
  const seenIds = new Set();

  output.people = rawPeople.flatMap((rawPerson, index) => {
    const name = normalizeName(rawPerson?.name);
    if (!name) return [];

    let id = String(rawPerson?.id || makeId());
    if (seenIds.has(id)) id = makeId();
    seenIds.add(id);

    const defaultStatus = isValidStatus(rawPerson?.defaultStatus)
      ? rawPerson.defaultStatus
      : "present";

    return [{
      id,
      name,
      defaultStatus,
      active: rawPerson?.active !== false,
      sortOrder: Number.isFinite(rawPerson?.sortOrder) ? rawPerson.sortOrder : index,
      createdAt: Number(rawPerson?.createdAt) || now,
      updatedAt: Number(rawPerson?.updatedAt) || now,
      archivedAt: rawPerson?.archivedAt ? Number(rawPerson.archivedAt) : null
    }];
  });

  output.people.sort((left, right) => left.sortOrder - right.sortOrder || left.createdAt - right.createdAt);
  output.people.forEach((person, index) => {
    person.sortOrder = index;
  });

  const knownIds = new Set(output.people.map((person) => person.id));
  if (input.attendance && typeof input.attendance === "object") {
    for (const [dateKey, rawDay] of Object.entries(input.attendance)) {
      if (!isDateKey(dateKey) || !rawDay || typeof rawDay !== "object") continue;
      const day = {};

      for (const [personId, rawEntry] of Object.entries(rawDay)) {
        if (!knownIds.has(personId)) continue;
        const status = typeof rawEntry === "string" ? rawEntry : rawEntry?.status;
        if (!isValidStatus(status)) continue;
        day[personId] = {
          status,
          source: ["default", "manual", "bulk"].includes(rawEntry?.source)
            ? rawEntry.source
            : "manual",
          updatedAt: Number(rawEntry?.updatedAt) || now
        };
      }

      output.attendance[dateKey] = day;
    }
  }

  if (input.initializedDays && typeof input.initializedDays === "object") {
    for (const [dateKey, rawDay] of Object.entries(input.initializedDays)) {
      if (!isDateKey(dateKey)) continue;
      output.initializedDays[dateKey] = {
        initializedAt: Number(rawDay?.initializedAt) || now,
        updatedAt: Number(rawDay?.updatedAt) || now
      };
    }
  }

  for (const dateKey of Object.keys(output.attendance)) {
    output.initializedDays[dateKey] ??= { initializedAt: now, updatedAt: now };
  }

  const requestedWindow = Number(input.settings?.historyWindowDays);
  output.settings.historyWindowDays = Number.isInteger(requestedWindow) && requestedWindow >= 1
    ? Math.min(requestedWindow, 366)
    : HISTORY_WINDOW_DAYS;
  output.revision = Number.isSafeInteger(input.revision) && input.revision >= 0 ? input.revision : 0;
  output.updatedAt = Number(input.updatedAt) || now;
  return output;
}

export function initializeDay(state, dateKey, { seedDefaults = false, timestamp = Date.now() } = {}) {
  state.attendance[dateKey] ??= {};
  const wasInitialized = Boolean(state.initializedDays[dateKey]);
  state.initializedDays[dateKey] ??= { initializedAt: timestamp, updatedAt: timestamp };

  if (!wasInitialized && seedDefaults) {
    for (const person of getActivePeople(state)) {
      state.attendance[dateKey][person.id] = {
        status: person.defaultStatus,
        source: "default",
        updatedAt: timestamp
      };
    }
  }

  state.initializedDays[dateKey].updatedAt = timestamp;
  state.updatedAt = timestamp;
  return !wasInitialized;
}

export function addPeople(state, rawNames, dateKey = toDateKey(), timestamp = Date.now()) {
  const names = (Array.isArray(rawNames) ? rawNames : String(rawNames ?? "").split(/\r?\n/))
    .map(normalizeName)
    .filter(Boolean);

  if (!names.length) return [];

  initializeDay(state, dateKey, { timestamp });
  const people = names.map((name, offset) => ({
    id: makeId(),
    name,
    defaultStatus: "present",
    active: true,
    sortOrder: state.people.length + offset,
    createdAt: timestamp + offset,
    updatedAt: timestamp + offset,
    archivedAt: null
  }));

  state.people.push(...people);
  for (const person of people) {
    state.attendance[dateKey][person.id] = {
      status: "present",
      source: "default",
      updatedAt: timestamp
    };
  }
  state.updatedAt = timestamp;
  return people;
}

export function setPersonStatus(state, dateKey, personId, status, timestamp = Date.now()) {
  if (!isValidStatus(status)) throw new TypeError(`Unknown attendance status: ${status}`);
  const person = state.people.find((candidate) => candidate.id === personId && candidate.active);
  if (!person) return null;

  initializeDay(state, dateKey, { timestamp });
  const previous = {
    entry: state.attendance[dateKey][personId]
      ? clone(state.attendance[dateKey][personId])
      : null,
    defaultStatus: person.defaultStatus
  };

  state.attendance[dateKey][personId] = { status, source: "manual", updatedAt: timestamp };
  person.defaultStatus = status;
  person.updatedAt = timestamp;
  state.updatedAt = timestamp;
  return previous;
}

export function setAllActivePeopleStatus(state, dateKey, status, timestamp = Date.now()) {
  if (!isValidStatus(status)) throw new TypeError(`Unknown attendance status: ${status}`);
  initializeDay(state, dateKey, { timestamp });

  const snapshot = getActivePeople(state).map((person) => ({
    personId: person.id,
    entry: state.attendance[dateKey][person.id]
      ? clone(state.attendance[dateKey][person.id])
      : null,
    defaultStatus: person.defaultStatus
  }));

  for (const person of getActivePeople(state)) {
    state.attendance[dateKey][person.id] = { status, source: "bulk", updatedAt: timestamp };
    person.defaultStatus = status;
    person.updatedAt = timestamp;
  }

  state.updatedAt = timestamp;
  return snapshot;
}

export function restoreBulkSnapshot(state, dateKey, snapshot, timestamp = Date.now()) {
  initializeDay(state, dateKey, { timestamp });
  for (const item of snapshot) {
    const person = state.people.find((candidate) => candidate.id === item.personId);
    if (!person) continue;
    if (item.entry) state.attendance[dateKey][person.id] = clone(item.entry);
    else delete state.attendance[dateKey][person.id];
    if (isValidStatus(item.defaultStatus)) person.defaultStatus = item.defaultStatus;
    person.updatedAt = timestamp;
  }
  state.updatedAt = timestamp;
}

export function fillMissingFromDefaults(state, dateKey, timestamp = Date.now()) {
  initializeDay(state, dateKey, { timestamp });
  let filled = 0;

  for (const person of getActivePeople(state)) {
    if (state.attendance[dateKey][person.id]) continue;
    state.attendance[dateKey][person.id] = {
      status: person.defaultStatus,
      source: "default",
      updatedAt: timestamp
    };
    filled += 1;
  }

  state.updatedAt = timestamp;
  return filled;
}

export function getActivePeople(state) {
  return state.people
    .filter((person) => person.active)
    .sort((left, right) => left.sortOrder - right.sortOrder);
}

export function getArchivedPeople(state) {
  return state.people
    .filter((person) => !person.active)
    .sort((left, right) => left.sortOrder - right.sortOrder);
}

export function getEntry(state, dateKey, personId) {
  return state.attendance[dateKey]?.[personId] ?? null;
}

export function getDailyCounts(state, dateKey) {
  const counts = { present: 0, sick: 0, drunk: 0, absent: 0, missing: 0, total: 0 };
  const day = state.attendance[dateKey] ?? {};

  for (const person of getActivePeople(state)) {
    counts.total += 1;
    const status = day[person.id]?.status;
    if (isValidStatus(status)) counts[status] += 1;
    else counts.missing += 1;
  }
  return counts;
}

export function getOverviewPeople(state) {
  return getActivePeople(state);
}

export function renamePerson(state, personId, rawName, timestamp = Date.now()) {
  const person = state.people.find((candidate) => candidate.id === personId);
  const name = normalizeName(rawName);
  if (!person || !name || person.name === name) return false;
  person.name = name;
  person.updatedAt = timestamp;
  state.updatedAt = timestamp;
  return true;
}

export function archivePerson(state, personId, timestamp = Date.now()) {
  const person = state.people.find((candidate) => candidate.id === personId && candidate.active);
  if (!person) return false;
  person.active = false;
  person.archivedAt = timestamp;
  person.updatedAt = timestamp;
  state.updatedAt = timestamp;
  return true;
}

export function restorePerson(state, personId, timestamp = Date.now()) {
  const person = state.people.find((candidate) => candidate.id === personId && !candidate.active);
  if (!person) return false;
  person.active = true;
  person.archivedAt = null;
  person.updatedAt = timestamp;
  state.updatedAt = timestamp;
  return true;
}

export function movePerson(state, personId, direction, timestamp = Date.now()) {
  const activePeople = getActivePeople(state);
  const index = activePeople.findIndex((person) => person.id === personId);
  const targetIndex = index + direction;
  if (index < 0 || targetIndex < 0 || targetIndex >= activePeople.length) return false;

  const target = activePeople[targetIndex];
  const current = activePeople[index];
  [current.sortOrder, target.sortOrder] = [target.sortOrder, current.sortOrder];
  current.updatedAt = timestamp;
  target.updatedAt = timestamp;
  state.updatedAt = timestamp;
  return true;
}

export function createBackupPayload(state, timestamp = Date.now()) {
  return {
    format: "attendance-pwa-backup",
    formatVersion: 1,
    exportedAt: timestamp,
    state: normalizeState(state, timestamp)
  };
}

export function restoreBackupPayload(payload, timestamp = Date.now()) {
  if (payload?.format !== "attendance-pwa-backup" || payload?.formatVersion !== 1 || !payload.state) {
    throw new TypeError("Unsupported backup file");
  }
  const restored = normalizeState(payload.state, timestamp);
  restored.updatedAt = timestamp;
  return restored;
}

export function statusDistribution(state, dateKey, people) {
  const counts = Object.fromEntries(STATUS_KEYS.map((status) => [status, 0]));
  counts.missing = 0;
  const day = state.attendance[dateKey] ?? {};
  for (const person of people) {
    const status = day[person.id]?.status;
    if (isValidStatus(status)) counts[status] += 1;
    else counts.missing += 1;
  }
  return counts;
}
